import{_ as t,o as a,c as s,a0 as n}from"./chunks/framework.BxCN1dRw.js";const g=JSON.parse('{"title":"Walkthrough: Reusing the same pages in an Electron desktop shell","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/electron-shell"},"headers":[],"relativePath":"en/tutorials/electron-shell.md","filePath":"en/tutorials/electron-shell.md"}'),o={name:"en/tutorials/electron-shell.md"};function r(i,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="walkthrough-reusing-the-same-pages-in-an-electron-desktop-shell" tabindex="-1">Walkthrough: Reusing the same pages in an Electron desktop shell <a class="header-anchor" href="#walkthrough-reusing-the-same-pages-in-an-electron-desktop-shell" aria-label="Permalink to &quot;Walkthrough: Reusing the same pages in an Electron desktop shell&quot;">​</a></h1><p>This chapter answers &quot;where does the desktop app come from&quot;. The desktop shell is not a second product: it loads the same-origin web entry that browsers use into an Electron window, and the pages, the API contract and the session cookie all come from shared code. There is no offline editing and no second sign-in protocol.</p><h2 id="_1-start-the-stack-and-open-the-shell" tabindex="-1">1. Start the stack and open the shell <a class="header-anchor" href="#_1-start-the-stack-and-open-the-shell" aria-label="Permalink to &quot;1. Start the stack and open the shell&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span></code></pre></div><p><code>just dev</code> starts PostgreSQL/RustFS/Redis, the API and the Web entry as usual; <code>just desktop</code> loads that same web entry into an Electron window (default <a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a>, adjustable through <code>SAAS_DESKTOP_ORIGIN</code> or <code>WEB_PORT</code> in <code>.env</code>). Registering, signing in, opening &quot;My documents&quot; and previewing Markdown inside the shell behaves exactly like the browser: the pages are rendered by the same <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/37d70e3aefd5f78e96a413090b5282b1a8169254/apps/web/src/router.tsx" target="_blank" rel="noreferrer">web router</a> and the requests go through the same generated SDK.</p><p>The session cookie lives in the shell&#39;s dedicated persistent partition <code>persist:saas-desktop</code>, independent of the system browser; the login survives a shell restart. Signing out revokes the server session, so the matching sessions in the shell and in browsers end together.</p><h2 id="_2-the-shell-only-wires-the-platform-never-the-business" tabindex="-1">2. The shell only wires the platform, never the business <a class="header-anchor" href="#_2-the-shell-only-wires-the-platform-never-the-business" aria-label="Permalink to &quot;2. The shell only wires the platform, never the business&quot;">​</a></h2><p>The shell is three parts: the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/37d70e3aefd5f78e96a413090b5282b1a8169254/apps/desktop/src/main.ts" target="_blank" rel="noreferrer">main process</a>, the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/37d70e3aefd5f78e96a413090b5282b1a8169254/apps/desktop/src/preload.ts" target="_blank" rel="noreferrer">preload bridge</a> and one local error page. The window is created with <code>contextIsolation: true</code>, <code>nodeIntegration: false</code>, <code>sandbox: true</code> and <code>&lt;webview&gt;</code> disabled. The renderer never touches Node or the session secret — it only loads same-origin pages; the cookie stays in Chromium&#39;s network stack and never enters IPC.</p><p>Navigation constraints are enforced in the shell:</p><ul><li>Only the app&#39;s same-origin address may load. Links to external sites do not take the window anywhere; they open in the system browser (http/https only, other schemes are ignored).</li><li><code>window.open</code>/<code>target=&quot;_blank&quot;</code> popups are always refused; external targets still go to the system browser.</li><li>Website permission requests (camera, notifications, …) are all denied by default.</li><li>Certificate errors follow Chromium&#39;s default strict handling; the shell allows nothing through.</li></ul><p>The preload exposes exactly six capabilities through the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/37d70e3aefd5f78e96a413090b5282b1a8169254/apps/desktop/src/ipc-contract.ts" target="_blank" rel="noreferrer">IPC contract</a>: reading the shell version/platform, retrying the load, opening the downloads folder, subscribing to download state events, and reading and writing the appearance preferences (the language and theme enums). Every payload is contract-validated on both sides, malformed events are dropped and illegal preference values are rejected; the http/https-only policy for the system-browser handoff is part of the same contract. The contract has no secret fields and no file contents — files are written by the main process and never travel over IPC.</p><p>The preference channels are the one cross-origin channel, and they exist for the local error page: the error page loads from <code>file://</code> and cannot read the app origin&#39;s localStorage, so a platform adapter in the web entry (<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/37d70e3aefd5f78e96a413090b5282b1a8169254/apps/web/src/desktop-preferences.tsx" target="_blank" rel="noreferrer">desktop-preferences.tsx</a> — active only inside the desktop shell, a no-op in browsers) mirrors the current language and theme to the shell, which stores them in a small JSON file in the user-data directory. Only the two enum values ever cross — session data, credentials, business objects and file paths never do. The desktop shell and the system browser persist their preferences independently. This wiring lives in the shell and the shared web entry, so it is composition-agnostic: the Core-only combination and the combination with the knowledge example behave identically.</p><h2 id="_3-controlled-deep-link-and-download-entries" tabindex="-1">3. Controlled deep-link and download entries <a class="header-anchor" href="#_3-controlled-deep-link-and-download-entries" aria-label="Permalink to &quot;3. Controlled deep-link and download entries&quot;">​</a></h2><p>Deep links look like <code>saas://open/&lt;in-app-path&gt;</code>. After parsing, the main process requires the <code>saas:</code> protocol, the <code>open</code> host and an absolute same-origin in-app path (absolute URLs, protocol-relative paths, backslash bypasses and raw whitespace are all rejected). A valid deep link focuses the existing window and navigates it — sending <code>saas://open/notifications</code> to a running shell focuses the window and opens the notifications page. Invalid deep links are ignored silently, with no navigation and no logging of the target. The shell holds a single-instance lock: a second launch only focuses the existing window and delivers the deep link instead of opening a second window.</p><p>The download entry listens to the partition&#39;s <code>will-download</code> event: only downloads started by an app-origin page are accepted, saved into the <code>SaasTemplate</code> subdirectory of the system downloads folder (override with <code>SAAS_DESKTOP_DOWNLOADS_DIR</code>); same-named files get a sequence suffix and existing files are never overwritten. The shared pages&#39; attachment and export downloads take exactly this path through in-page blobs; downloads from any other origin are cancelled outright. Progress and results reach the page as contract events, and the filename is sanitized so it is always a single safe path segment.</p><p>When the main document fails to load, the window switches to the local error page, and &quot;Reconnect&quot; returns to the address that failed. A renderer crash returns to the error page too, so there is never a blank window. The error page continues the app&#39;s appearance language: it reads the saved language and theme from the shell and renders accordingly — bilingual title, description, button and accessible names, with reachable focus and contrast in both themes. Before the app has ever run it falls back to the device preferences, and &quot;system&quot; follows the operating system&#39;s light/dark switch live. Closing the last window quits the app; a failed protocol registration does not affect development (deep links still arrive through second-instance arguments).</p><h2 id="_4-tests-and-ci-split" tabindex="-1">4. Tests and CI split <a class="header-anchor" href="#_4-tests-and-ci-split" aria-label="Permalink to &quot;4. Tests and CI split&quot;">​</a></h2><ul><li>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/37d70e3aefd5f78e96a413090b5282b1a8169254/apps/desktop/src/ipc-contract.test.ts" target="_blank" rel="noreferrer">IPC contract tests</a> (Vitest) cover the bridge shape, deep-link path normalization, filename sanitization, download event validation and the preference enum validation — no GUI required, part of the default <code>just check</code>.</li><li>The shell GUI smoke: <code>just desktop-smoke</code> boots the real stack (PostgreSQL/RustFS/Redis/Mailpit/API/Web) and drives a real Electron with Playwright: launch, sign-in/out, knowledge document browsing with Markdown preview, app-page download to disk and cross-origin download refusal, external-link handoff to the system browser, valid and invalid deep links, the offline error page with retry recovery, and the error page&#39;s preference continuity — after switching language and theme in settings and cutting the connection, the error page renders in the chosen look, the choice survives a restart on the same user-data directory, and &quot;system&quot; follows the emulated OS switch. Business role matrices are not repeated here; they stay in the backend and shared view tests.</li><li>CI runs the GUI smoke as a separate <code>desktop-smoke</code> job (<code>xvfb-run</code> provides the X server on headless runners); the default main gate only includes the shell&#39;s type, build and contract checks.</li></ul><h2 id="_5-run-this-chapter-s-checks" tabindex="-1">5. Run this chapter&#39;s checks <a class="header-anchor" href="#_5-run-this-chapter-s-checks" aria-label="Permalink to &quot;5. Run this chapter&#39;s checks&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/desktop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop-smoke</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>The points that matter: the secret-free IPC contract, same-origin navigation constraints, deep links that reject external targets, downloads that come only from app pages and never overwrite files, and a recoverable error page that keeps the chosen look. The shell depends on Electron and a desktop environment, so it is an optional runtime: default development and <code>just check</code> require nothing beyond the desktop toolchain.</p><p>Packaging and distribution (installers, auto-update, multi-platform signing) are out of scope for template v1; the <code>dist/main.cjs</code> produced by <code>pnpm --filter @saas/desktop build</code> can go straight into any standard Electron packaging flow.</p><hr><p>Source version：<code>37d70e3aefd5</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/37d70e3aefd5f78e96a413090b5282b1a8169254/docs/tutorials/20-electron-shell.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,24)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
